#include <bits/stdc++.h>
using namespace std;
static inline uint64_t adjcode_order(const array<uint16_t,9>& a,const array<int,9>& ord){uint64_t code=0;int b=0;for(int i=0;i<9;i++)for(int j=i+1;j<9;j++,b++)if(a[ord[i]]&(1u<<ord[j]))code|=(1ULL<<b);return code;}
uint64_t canonical9(const array<uint16_t,9>& a){
 int col[9];vector<int>deg(9);for(int i=0;i<9;i++)deg[i]=__builtin_popcount((unsigned)a[i]);vector<int>ds=deg;sort(ds.begin(),ds.end());ds.erase(unique(ds.begin(),ds.end()),ds.end());for(int i=0;i<9;i++)col[i]=lower_bound(ds.begin(),ds.end(),deg[i])-ds.begin();
 for(int it=0;it<9;it++){int k=*max_element(col,col+9)+1;vector<vector<int>>sig(9,vector<int>(k+1));for(int i=0;i<9;i++){sig[i][0]=col[i];for(int j=0;j<9;j++)if(a[i]&(1u<<j))sig[i][1+col[j]]++;}vector<int>idx(9);iota(idx.begin(),idx.end(),0);sort(idx.begin(),idx.end(),[&](int x,int y){return sig[x]<sig[y];});int nc[9],c=-1;vector<int>prev;for(int pos=0;pos<9;pos++){int v=idx[pos];if(pos==0||sig[v]!=prev){c++;prev=sig[v];}nc[v]=c;}bool same=true;for(int i=0;i<9;i++)if(nc[i]!=col[i]){same=false;break;}for(int i=0;i<9;i++)col[i]=nc[i];if(same)break;}
 int k=*max_element(col,col+9)+1;vector<vector<int>>cells(k);for(int i=0;i<9;i++)cells[col[i]].push_back(i);array<int,9>ord{};int offset[10];offset[0]=0;for(int c=0;c<k;c++)offset[c+1]=offset[c]+cells[c].size();uint64_t best=0;bool first=true;function<void(int)>rec=[&](int ci){if(ci==k){uint64_t code=adjcode_order(a,ord);if(first||code<best){best=code;first=false;}return;}auto v=cells[ci];sort(v.begin(),v.end());do{for(int t=0;t<(int)v.size();t++)ord[offset[ci]+t]=v[t];rec(ci+1);}while(next_permutation(v.begin(),v.end()));};rec(0);return best;
}
vector<array<uint16_t,8>> read_g6_8(const string&path){ifstream in(path,ios::binary);string s;vector<array<uint16_t,8>>out;while(getline(in,s)){if(!s.empty()&&s.back()=='\r')s.pop_back();if(s.empty())continue;int pos=0,n=(unsigned char)s[pos++]-63;if(n!=8){cerr<<"bad n "<<n<<"\n";exit(2);}array<uint16_t,8>a{};int val=0,rem=0;auto nextbit=[&](){if(rem==0){val=((unsigned char)s[pos++])-63;rem=6;}int bit=(val>>(rem-1))&1;rem--;return bit;};for(int j=1;j<n;j++)for(int i=0;i<j;i++)if(nextbit()){a[i]|=(1u<<j);a[j]|=(1u<<i);}out.push_back(a);}return out;}
int main(int argc,char**argv){if(argc!=3){cerr<<"usage: bmo_n9_canon_exact N8_G6 N9_CODES\n";return 2;}auto base=read_g6_8(argv[1]);cerr<<"loaded "<<base.size()<<"\n";unordered_set<uint64_t>seen;seen.reserve(400000);long long cand=0;mt19937 rng(12345);for(int z=0;z<min<int>(100,base.size());z++){array<uint16_t,9>a{};for(int i=0;i<8;i++)a[i]=base[z][i];a[8]=1;a[0]|=(1u<<8);auto c0=canonical9(a);for(int r=0;r<5;r++){array<int,9>p;iota(p.begin(),p.end(),0);shuffle(p.begin(),p.end(),rng);array<uint16_t,9>q{};for(int i=0;i<9;i++)for(int j=i+1;j<9;j++)if(a[i]&(1u<<j)){q[p[i]]|=(1u<<p[j]);q[p[j]]|=(1u<<p[i]);}if(canonical9(q)!=c0){cerr<<"CANON_INVARIANCE_FAIL\n";return 3;}}}cerr<<"canon validation pass\n";for(size_t bi=0;bi<base.size();bi++){for(int mask=1;mask<256;mask++){array<uint16_t,9>a{};for(int i=0;i<8;i++)a[i]=base[bi][i];for(int i=0;i<8;i++)if(mask&(1<<i)){a[i]|=(1u<<8);a[8]|=(1u<<i);}seen.insert(canonical9(a));cand++;}}cout<<"n9_augmentation_candidates="<<cand<<"\n";cout<<"n9_connected_isomorphism_classes="<<seen.size()<<"\n";cout<<"standard_count_sanity="<<(seen.size()==261080?"PASS":"FAIL")<<"\n";vector<uint64_t>codes(seen.begin(),seen.end());sort(codes.begin(),codes.end());ofstream out(argv[2]);for(auto c:codes)out<<c<<"\n";return seen.size()==261080?0:4;}
